const express = require('express');
const app = express();
const port = process.env.PORT || 3000;

app.use(express.json());

/**
 * Evaluate a caller‑supplied rule expression against the request.
 * The request body must contain a `rule` string and optionally a `context` object.
 * Example body:
 * {
 *   "rule": "ctx.amount > 100",
 *   "context": { "amount": 150 }
 * }
 */
function evalRule(req) {
  const expr = req.body.rule;
  if (typeof expr !== 'string') {
    throw new Error('Rule must be a string');
  }
  const ctx = { ctx: req.body.context ?? {}, req };
  // Use Function constructor for dynamic evaluation – best effort sandbox
  return Function('ctx', 'req', `return (${expr});`)(ctx.ctx, req);
}

app.post('/check', (req, res) => {
  try {
    const result = evalRule(req);
    res.json({ result });
  } catch (err) {
    console.error('Error evaluating rule:', err);
    res.status(400).json({ error: err.message });
  }
});

app.listen(port, () => {
  console.log(`Rule engine listening on port ${port}`);
});

